#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int height;
    int index;
} Rectangle;

int compare_rectangles(const void *a, const void *b) {
    const Rectangle *x = (const Rectangle *)a;
    const Rectangle *y = (const Rectangle *)b;

    if (x->height > y->height) return -1;
    if (x->height < y->height) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Rectangle *rectangles = malloc((size_t)n * sizeof(Rectangle));
    char *active = calloc((size_t)n, sizeof(char));

    for (int i = 0; i < n; i++) {
        scanf("%d", &rectangles[i].height);
        rectangles[i].index = i;
    }

    qsort(rectangles, (size_t)n, sizeof(Rectangle), compare_rectangles);

    int runs = 0;
    int max_runs = 0;

    for (int i = 0; i < n;) {
        int j = i;
        while (j < n && rectangles[j].height == rectangles[i].height) {
            int pos = rectangles[j].index;
            active[pos] = 1;
            runs++;

            if (pos > 0 && active[pos - 1]) runs--;
            if (pos + 1 < n && active[pos + 1]) runs--;

            j++;
        }

        if (runs > max_runs) max_runs = runs;
        i = j;
    }

    printf("%d\n", max_runs + 1);

    free(active);
    free(rectangles);
    return 0;
}
